  WH = `An manchen Tagen tut es nur ein Spiel mit tiefgründiger Story und dieses Spiel ist Story pur. So ergreifend wie eine Seifenoper, so fein abgestimmt wie ein Prestige-Fernsehfilm\xA0–\xA0Hut ab! Wir fühlen mit!`,
