  $fe = `Einer Ihrer letzten Handel wurde von Ihrem Handelspartner rückgängig gemacht.`,
  epe = `Spieler erreichten während des Spielens von %3$s durchschnittlich %2$s auf folgendem Gerät: %1$s`,
  tpe = `Spieler erreichten während des Spielens dieses Titels durchschnittlich %2$s auf folgendem Gerät: %1$s`,
  npe = `%1$s\xA0FPS`,
  rpe = `Zuletzt aktualisiert: %1$s`,
  ipe = `Anonymisierte Daten zur Bildrate:`,
  ape = `Anonymisierte Daten zur Bildrate`,
  ope = `Gestatten Sie Steam, während des Spielens sowie der aktiven Nutzung des Steam-Accounts anonyme Daten zur Bildrate zu sammeln? Diese Daten werden zur Kompatibilitätsprüfung von Spielen sowie zur Verbesserung von Steam verwendet.`,
  spe = `Anonymisierte Daten zur Bildrate`,
  cpe = `Durch die Aktivierung dieser Option, werden beim Spielen Daten zur Bildrate erfasst und gespeichert. Diese Daten enthalten keine accountbezogenen Informationen, geben jedoch Aufschluss darüber, welche Hardware zum Spielen verwendet wurde. Die Erfassung dieser Daten gibt Steam Aufschluss über die Kompatibilität von Spielen und trägt so zur Verbesserung der allgemeinen Spielerfahrung auf Geräten mit Steam bei.`,
  lpe = `Sie können diese Einstellung jederzeit unter <1>Accountdetails > Daten und Browsernutzung</1> ändern.`,
  upe = `Mehr erfahren`,
  dpe = `Steam-Deck-Kompatibilität`,
  fpe = `Für das Steam Deck verifiziert\xA0– Kundenfeedback`,
  ppe = `Keine Daten verfügbar`,
  mpe = `%1$s der Befragten stimmen der Bewertung „%2$s“ für dieses Spiel zu.`,
  hpe = `Zum Vergleich: Die durchschnittliche Zustimmungsrate aller für das Steam Deck verifizierten Spiele liegt bei %1$s.`,
  gpe = `%1$s %`,
  _pe = `Wir stellen diese Daten zur Verfügung, da Kunden zwar überwiegend der Bewertung der Steam-Deck-Kompatibilitätsprüfung zustimmen (über %1$s %), es aber für Entwickler wertvoll sein kann, die Erfahrungen von Kunden, die anderer Meinung sind, besser zu verstehen, insbesondere im Zusammenhang mit einem bestimmten Titel oder Update.`,
  vpe = `Leistung`,
  ype = `Lesbarkeit`,
  bpe = `Stabilität`,
  xpe = `Eingabe`,
  Spe = `Andere Gründe`,
  Cpe = `Diese Daten basieren auf %1$s Meldungen der letzten %2$s Tage von Kunden, die sich dazu bereit erklärt haben, Feedback zum Steam Deck zu hinterlassen.`,
  wpe = `Kunden, die dem Status „%2$s“ des Spiels %1$s, gaben folgende Gründe dafür an:`,
  Tpe = `nicht zustimmten`,
  Epe = `Daten zur Bildrate des Steam Deck`,
  Dpe = `Durchschnittliche Steam-Deck-Bildrate`,
  Ope = `Die durchschnittlich gemeldete Bildrate für %1$s auf %2$s beträgt %3$s`,
  kpe = `Die durchschnittlich gemeldete Bildrate für dieses Spiel auf %1$s beträgt %2$s`,
  Ape = `%1$s\xA0FPS`,
  jpe = `Die Daten zur Bildrate des Steam Deck basieren auf Meldungen im Zeitraum von %1$s Tagen von Kunden, die sich dazu bereit erklärt haben, die Daten zur Bildrate ihres Geräts zu teilen.`,
  Mpe = `Die Daten zur Bildrate des Steam Deck basieren auf Meldungen von Kunden, die sich dazu bereit erklärt haben, die Daten zur Bildrate ihres Geräts zu teilen.`,
  Npe = `Hinweis: Die Varianz wird derzeit nicht angezeigt, ist aber für die Beta-Phase geplant. Mithilfe der Varianzdaten können Sie erkennen, ob die Bildrate konstant ist oder stark schwankt.`,
  Ppe = `Begründung`,
  Fpe = `Anzahl der Antworten`,
  Ipe = `Die Histogrammdaten für %1$s basieren auf Meldungen von Kunden, die sich dazu bereit erklärt haben, die Daten zur Bildrate Ihres Geräts (%2$s) zu teilen.`,
  Lpe = `Die Histogrammdaten dieses Spiels basieren auf Meldungen von Kunden, die sich dazu bereit erklärt haben, die Daten zur Bildrate Ihres Geräts (%1$s) zu teilen.`,
  Rpe = `Bildratenverteilung`,
  zpe = `Bildrate`,
  Bpe = `\xA0% der Stichproben`,
  Vpe = `Es wird ein Diagramm angezeigt, sobald ausreichend Daten vorliegen`,
  Hpe = `Alle Daten miteinbeziehen`,
  Upe = `Standardmäßig werden Daten herausgefiltert, wenn das Gerät nicht auf die standardmäßige Bildrateneinschränkung eingestellt ist.`,
  Wpe = `Steam Deck LCD`,
  Gpe = `Steam Deck OLED`,
  Kpe = `Steam-Deck-Modell`,
  qpe = `Bildratenverteilung`,
  Jpe = `Steam sammelt zurzeit noch Daten zur Bildrate für %1$s auf folgendem Gerät: %2$s`,
  Ype = `Steam sammelt zurzeit noch Daten zur Bildrate für dieses Spiel auf folgendem Gerät: %1$s`,
  Xpe = `Steam sammelt zurzeit noch Daten zur Bildrate für dieses Spiel.`,
  Zpe = `Dieses Diagramm zeigt Bildraten-Stichproben von Kunden, die der Bereitstellung von anonymisierten Daten beim Spielen von %1$s auf folgendem Gerät zugestimmt haben: %2$s. Jeder Balken gibt den Prozentsatz der mit dieser Bildrate gemessenen Stichproben an.`,
  Qpe = `Dieses Diagramm zeigt Bildraten-Stichproben von Kunden, die der Bereitstellung von anonymisierten Daten beim Spielen dieses Titels auf folgendem Gerät zugestimmt haben: %1$s. Jeder Balken gibt den Prozentsatz der mit dieser Bildrate gemessenen Stichproben an.`,
  $pe = `Weitere Details`,
  eme = `Es werden nur Daten berücksichtigt, die bei der standardmäßigen Bildrateneinschränkung von %2$s FPS für dieses Gerät (%1$s) erfasst wurden. Leerlaufzeiten und ungültige Stichproben werden herausgefiltert. Während jeder Spielsitzung werden mehrere Stichproben erfasst.`,
  tme = `In diesem Diagramm verzeichnete Sprünge, wie bspw. von %1$s auf %2$s FPS, können durch VSync verursacht werden, welches die Bildrate mit der Bildwiederholfrequenz der Anzeige synchronisiert, um Tearing zu verhindern. Dadurch können sich Stichproben von %1$s und %2$s FPS häufen, selbst wenn die durchschnittliche Bildrate des Spiels zwischen diesen Werten liegt. Dies ist ein durch VSync erwartetes Verhalten, welches die Bildwiederholungsfrequenz zwar beeinflussen kann, jedoch nicht zwangsläufig zu spürbaren Rucklern führt.`,
  nme = `BETA`,
  rme = `Ein Workshop-Inhalt für %1$s`,
  ime = `Ein Screenshot von %1$s`,
  ame = `Ein Video von %1$s`,
  ome = `Von der Community erstelltes Artwork zu %1$s`,
